<section class="analytics-hero compact"><div><p class="section-kicker">Approximate location</p><h2>Where your audience visits from</h2><p>Country, region, and city appear only when your host provides trusted GeoIP data. Core never calls a location API and never stores raw IP addresses.</p></div><form class="analytics-range" method="get" action="<?= e_attr($siteBasePath) ?>/index.php"><input type="hidden" name="p" value="/admin/analytics/geography"><label>From<input type="date" name="from" value="<?= e_attr($data['from']) ?>"></label><label>To<input type="date" name="to" value="<?= e_attr($data['to']) ?>"></label><button class="btn">Apply</button></form></section>
<?php if(!$enabled): ?><div class="notice warning"><strong>Geography collection is paused.</strong> Enable it from the Analytics dashboard when location reporting is needed.</div><?php endif; ?>
<div class="analytics-grid geography-grid"><?php foreach(['countries'=>'Countries','regions'=>'Regions','cities'=>'Cities'] as $key=>$title): ?><section class="analytics-panel"><div class="card-heading"><h2><?= e($title) ?></h2><span class="badge neutral"><?= count($data[$key]) ?> measured</span></div><?php if(!$data[$key]): ?><div class="empty-state"><strong>No measured locations</strong><span>Your host may not provide local GeoIP headers yet. Traffic remains counted as Unknown.</span></div><?php else: ?><ol class="analytics-rank"><?php $max=max(1,...array_column($data[$key],'value'));foreach($data[$key] as $row): ?><li><span><?= e($row['label']) ?></span><span class="analytics-bar"><i style="width:<?= round($row['value']/$max*100,1) ?>%"></i></span><strong><?= (int)$row['value'] ?></strong></li><?php endforeach; ?></ol><?php endif; ?></section><?php endforeach; ?></div>
